CREATE TABLE IF NOT EXISTS clients (id TEXT PRIMARY KEY, workspace TEXT NOT NULL CHECK(workspace IN ('demo','live')), project_id TEXT, name_key TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(workspace,name_key));
CREATE TABLE IF NOT EXISTS migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, workspace TEXT NOT NULL CHECK(workspace IN ('demo','live')), project_id TEXT, data TEXT NOT NULL, client_id TEXT REFERENCES clients(id) ON DELETE RESTRICT, UNIQUE(id,workspace));
CREATE TABLE IF NOT EXISTS environments (id TEXT PRIMARY KEY, workspace TEXT NOT NULL CHECK(workspace IN ('demo','live')), project_id TEXT, data TEXT NOT NULL, FOREIGN KEY(project_id,workspace) REFERENCES projects(id,workspace) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, workspace TEXT NOT NULL CHECK(workspace IN ('demo','live')), project_id TEXT, data TEXT NOT NULL, FOREIGN KEY(project_id,workspace) REFERENCES projects(id,workspace) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS accesses (id TEXT PRIMARY KEY, workspace TEXT NOT NULL CHECK(workspace IN ('demo','live')), project_id TEXT, data TEXT NOT NULL, FOREIGN KEY(project_id,workspace) REFERENCES projects(id,workspace) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS resources (id TEXT PRIMARY KEY, workspace TEXT NOT NULL CHECK(workspace IN ('demo','live')), project_id TEXT, data TEXT NOT NULL, FOREIGN KEY(project_id,workspace) REFERENCES projects(id,workspace) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS inventories (id TEXT PRIMARY KEY, workspace TEXT NOT NULL CHECK(workspace IN ('demo','live')), project_id TEXT, data TEXT NOT NULL, FOREIGN KEY(project_id,workspace) REFERENCES projects(id,workspace) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS components (id TEXT PRIMARY KEY, workspace TEXT NOT NULL CHECK(workspace IN ('demo','live')), project_id TEXT, data TEXT NOT NULL, FOREIGN KEY(project_id,workspace) REFERENCES projects(id,workspace) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS activity (id TEXT PRIMARY KEY, workspace TEXT NOT NULL CHECK(workspace IN ('demo','live')), project_id TEXT, data TEXT NOT NULL, FOREIGN KEY(project_id,workspace) REFERENCES projects(id,workspace) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "user" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz not null, "updatedAt" timestamptz not null);
CREATE TABLE IF NOT EXISTS "session" ("id" text not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" text not null references "user" ("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "account" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz not null, "updatedAt" timestamptz not null);
CREATE TABLE IF NOT EXISTS "verification" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz not null, "updatedAt" timestamptz not null);
CREATE TABLE IF NOT EXISTS hosting_connections (id TEXT PRIMARY KEY,workspace TEXT NOT NULL CHECK(workspace='live'),endpoint TEXT NOT NULL,username TEXT NOT NULL,data TEXT NOT NULL,secret_cipher TEXT,UNIQUE(workspace,endpoint,username));
CREATE TABLE IF NOT EXISTS hosting_installations (id TEXT PRIMARY KEY,workspace TEXT NOT NULL CHECK(workspace='live'),connection_id TEXT NOT NULL REFERENCES hosting_connections(id) ON DELETE CASCADE,scope TEXT NOT NULL,document_root TEXT NOT NULL,project_id TEXT,link_method TEXT,match_reason TEXT,data TEXT NOT NULL,UNIQUE(connection_id,scope,document_root),FOREIGN KEY(project_id,workspace) REFERENCES projects(id,workspace));
CREATE TABLE IF NOT EXISTS hosting_discovery_runs (connection_id TEXT NOT NULL REFERENCES hosting_connections(id) ON DELETE CASCADE,scope TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(connection_id,scope));
CREATE TABLE IF NOT EXISTS hosting_site_inventories (installation_id TEXT PRIMARY KEY REFERENCES hosting_installations(id) ON DELETE CASCADE,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hosting_observers (installation_id TEXT PRIMARY KEY REFERENCES hosting_installations(id) ON DELETE CASCADE,secret_cipher TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wordpress_catalog (cache_key TEXT PRIMARY KEY,data TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS railway_connections(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL UNIQUE,data TEXT NOT NULL,secret_cipher TEXT);
CREATE TABLE IF NOT EXISTS railway_projects(connection_id TEXT NOT NULL REFERENCES railway_connections(id) ON DELETE CASCADE,remote_id TEXT NOT NULL,project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,workspace TEXT NOT NULL DEFAULT 'live' CHECK(workspace='live'),link_method TEXT,observed_at TEXT NOT NULL,missing_since TEXT,data TEXT NOT NULL,PRIMARY KEY(connection_id,remote_id));
CREATE TABLE IF NOT EXISTS software_release_catalog(cache_key TEXT PRIMARY KEY,data TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vercel_connections(id TEXT PRIMARY KEY,team_id TEXT NOT NULL UNIQUE,data TEXT NOT NULL,secret_cipher TEXT);
CREATE TABLE IF NOT EXISTS vercel_projects(connection_id TEXT NOT NULL REFERENCES vercel_connections(id) ON DELETE CASCADE,remote_id TEXT NOT NULL,project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,link_method TEXT,observed_at TEXT NOT NULL,missing_since TEXT,data TEXT NOT NULL,PRIMARY KEY(connection_id,remote_id));
CREATE TABLE IF NOT EXISTS vercel_client_links(team_id TEXT NOT NULL,client_label TEXT NOT NULL,client_id TEXT REFERENCES clients(id) ON DELETE SET NULL,PRIMARY KEY(team_id,client_label));
CREATE UNIQUE INDEX IF NOT EXISTS projects_scope ON projects(id, workspace);
CREATE INDEX IF NOT EXISTS environments_workspace_project ON environments(workspace,project_id);
CREATE INDEX IF NOT EXISTS services_workspace_project ON services(workspace,project_id);
CREATE INDEX IF NOT EXISTS accesses_workspace_project ON accesses(workspace,project_id);
CREATE INDEX IF NOT EXISTS resources_workspace_project ON resources(workspace,project_id);
CREATE INDEX IF NOT EXISTS inventories_workspace_project ON inventories(workspace,project_id);
CREATE INDEX IF NOT EXISTS components_workspace_project ON components(workspace,project_id);
CREATE INDEX IF NOT EXISTS activity_workspace_project ON activity(workspace,project_id);
CREATE INDEX IF NOT EXISTS "session_userId_idx" on "session" ("userId");
CREATE INDEX IF NOT EXISTS "account_userId_idx" on "account" ("userId");
CREATE INDEX IF NOT EXISTS "verification_identifier_idx" on "verification" ("identifier");
CREATE INDEX IF NOT EXISTS projects_client ON projects(workspace,client_id);
CREATE INDEX IF NOT EXISTS hosting_installations_project ON hosting_installations(project_id);
CREATE INDEX IF NOT EXISTS railway_project_link ON railway_projects(project_id);
CREATE INDEX IF NOT EXISTS vercel_project_link ON vercel_projects(project_id);
